effect.shader:
// tempo do Node ligado ao motor (tools/nodevideo/ligar_tempo.py)
#define _cur_time acTime
vec4 u_xlat0;
bool u_xlatb0;
vec4 u_xlat1;
int u_xlati1;
bvec3 u_xlatb1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
bvec3 u_xlatb4;
vec4 u_xlat5;
bvec3 u_xlatb5;
vec3 u_xlat6;
bvec3 u_xlatb6;
vec3 u_xlat7;
vec3 u_xlat8;
bvec3 u_xlatb8;
vec2 u_xlat9;
uint u_xlatu9;
vec2 u_xlat18;
ivec2 u_xlati18;
float u_xlat27;
int u_xlati27;
bool u_xlatb27;
float u_xlat28;
void main()
{
    u_xlat0.x = acScreenNorm.y + (-_offset);
    u_xlat9.x = acScreenNorm.x * _horizontal_count;
    u_xlat18.x = u_xlat9.x * 3.14159274;
    u_xlat18.x = sin(u_xlat18.x);
    u_xlat18.x = u_xlat18.x + 1.0;
    u_xlat18.x = u_xlat18.x + (-_horizontal_spacing);
    u_xlati27 = int((0.0<u_xlat18.x) ? 0xFFFFFFFFu : uint(0));
    u_xlati18.x = int((u_xlat18.x<0.0) ? 0xFFFFFFFFu : uint(0));
    u_xlati18.x = (-u_xlati27) + u_xlati18.x;
    u_xlat18.x = float(u_xlati18.x);
    u_xlat9.x = floor(u_xlat9.x);
    u_xlat9.x = u_xlat9.x / _horizontal_count;
    u_xlatb1.xyz = equal(ivec4(_symmetry, _invert, _blend_mode, _symmetry), ivec4(1, 1, 1, 0)).xyz;
    u_xlat27 = u_xlat9.x * 2.0 + -1.0;
    u_xlat9.x = (u_xlatb1.x) ? abs(u_xlat27) : u_xlat9.x;
    u_xlat9.x = u_xlat9.x * 31.0;
    u_xlat9.x = floor(u_xlat9.x);
    u_xlat9.x = max(u_xlat9.x, 0.0);
    u_xlat9.x = min(u_xlat9.x, 30.0);
    u_xlatu9 = uint(u_xlat9.x);
    u_xlat9.x = u_xlat18.x * _bands[int(u_xlatu9)];
    u_xlat9.y = u_xlat0.x * _vertical_count;
    u_xlat9.xy = u_xlat9.xy * vec2(0.5, 3.14159274);
    u_xlat18.x = sin(u_xlat9.y);
    u_xlat18.x = u_xlat18.x + 1.0;
    u_xlat18.x = u_xlat18.x + (-_vertical_spacing);
    u_xlati27 = int((0.0<u_xlat18.x) ? 0xFFFFFFFFu : uint(0));
    u_xlati18.x = int((u_xlat18.x<0.0) ? 0xFFFFFFFFu : uint(0));
    u_xlati18.x = (-u_xlati27) + u_xlati18.x;
    u_xlatb27 = _enable_colour==1;
    u_xlat1.x = u_xlat0.x + -1.0;
    u_xlat28 = (-_cur_time) * _speed + acScreenNorm.x;
    u_xlat2.xyz = vec3(u_xlat28) + vec3(0.0, -0.333333343, -0.666666687);
    u_xlat2.xyz = fract(u_xlat2.xyz);
    u_xlat3.xyz = u_xlat2.xyz * vec3(3.0, 3.0, 3.0);
    u_xlatb4.xyz = greaterThanEqual(u_xlat2.xyzx, vec4(0.0, 0.0, 0.0, 0.0)).xyz;
    u_xlat4.x = u_xlatb4.x ? float(1.0) : 0.0;
    u_xlat4.y = u_xlatb4.y ? float(1.0) : 0.0;
    u_xlat4.z = u_xlatb4.z ? float(1.0) : 0.0;
;
    u_xlat5.xyz = (-u_xlat2.xyz) * vec3(3.0, 3.0, 3.0) + vec3(1.0, 1.0, 1.0);
    u_xlatb5.xyz = greaterThanEqual(u_xlat5.xyzx, vec4(0.0, 0.0, 0.0, 0.0)).xyz;
    u_xlat5.x = u_xlatb5.x ? float(1.0) : 0.0;
    u_xlat5.y = u_xlatb5.y ? float(1.0) : 0.0;
    u_xlat5.z = u_xlatb5.z ? float(1.0) : 0.0;
;
    u_xlat4.xyz = u_xlat4.xyz * u_xlat5.xyz;
    u_xlat5.xyz = u_xlat2.xyz * vec3(3.0, 3.0, 3.0) + vec3(-1.0, -1.0, -1.0);
    u_xlatb5.xyz = greaterThanEqual(u_xlat5.xyzx, vec4(0.0, 0.0, 0.0, 0.0)).xyz;
    u_xlat5.x = u_xlatb5.x ? float(1.0) : 0.0;
    u_xlat5.y = u_xlatb5.y ? float(1.0) : 0.0;
    u_xlat5.z = u_xlatb5.z ? float(1.0) : 0.0;
;
    u_xlat6.xyz = (-u_xlat2.xyz) * vec3(3.0, 3.0, 3.0) + vec3(2.0, 2.0, 2.0);
    u_xlatb6.xyz = greaterThanEqual(u_xlat6.xyzx, vec4(0.0, 0.0, 0.0, 0.0)).xyz;
    u_xlat6.x = u_xlatb6.x ? float(1.0) : 0.0;
    u_xlat6.y = u_xlatb6.y ? float(1.0) : 0.0;
    u_xlat6.z = u_xlatb6.z ? float(1.0) : 0.0;
;
    u_xlat5.xyz = u_xlat5.xyz * u_xlat6.xyz;
    u_xlat6.xyz = u_xlat2.xyz * vec3(3.0, 3.0, 3.0) + vec3(-2.0, -2.0, -2.0);
    u_xlatb6.xyz = greaterThanEqual(u_xlat6.xyzx, vec4(0.0, 0.0, 0.0, 0.0)).xyz;
    u_xlat6.x = u_xlatb6.x ? float(1.0) : 0.0;
    u_xlat6.y = u_xlatb6.y ? float(1.0) : 0.0;
    u_xlat6.z = u_xlatb6.z ? float(1.0) : 0.0;
;
    u_xlat7.xyz = (-u_xlat2.xyz) * vec3(3.0, 3.0, 3.0) + vec3(3.0, 3.0, 3.0);
    u_xlatb8.xyz = greaterThanEqual(u_xlat7.xyzx, vec4(0.0, 0.0, 0.0, 0.0)).xyz;
    u_xlat8.x = u_xlatb8.x ? float(1.0) : 0.0;
    u_xlat8.y = u_xlatb8.y ? float(1.0) : 0.0;
    u_xlat8.z = u_xlatb8.z ? float(1.0) : 0.0;
;
    u_xlat6.xyz = u_xlat6.xyz * u_xlat8.xyz;
    u_xlat3.xyz = u_xlat3.xyz * u_xlat3.xyz;
    u_xlat2.xyz = u_xlat2.xyz * vec3(18.0, 18.0, 18.0);
    u_xlat2.xyz = u_xlat3.xyz * vec3(-2.0, -2.0, -2.0) + u_xlat2.xyz;
    u_xlat2.xyz = u_xlat2.xyz + vec3(-3.0, -3.0, -3.0);
    u_xlat2.xyz = u_xlat2.xyz * u_xlat5.xyz;
    u_xlat2.xyz = u_xlat4.xyz * u_xlat3.xyz + u_xlat2.xyz;
    u_xlat3.xyz = u_xlat7.xyz * u_xlat7.xyz;
    u_xlat2.xyz = u_xlat6.xyz * u_xlat3.xyz + u_xlat2.xyz;
    u_xlat2.xyz = u_xlat2.xyz * vec3(0.5, 0.5, 0.5);
    u_xlat2.xyz = abs(u_xlat1.xxx) * u_xlat2.xyz;
    u_xlat2.xyz = bool(u_xlatb27) ? u_xlat2.xyz : vec3(0.0, 0.0, 0.0);
    u_xlat2.xyz = (-u_xlat2.xyz) + vec3(1.0, 1.0, 1.0);
    u_xlat3.xyz = u_xlat2.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat3.xyz = u_xlat2.xyz * u_xlat3.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat2.xyz = u_xlat2.xyz * u_xlat3.xyz;
    u_xlat3.xyz = u_xlat2.xyz * u_xlat2.xyz;
    u_xlat2.xyz = u_xlat2.xyz * u_xlat3.xyz;
    u_xlat27 = (-u_xlat0.x) + 1.0;
    u_xlat0.x = (u_xlatb1.y) ? u_xlat27 : u_xlat0.x;
    u_xlat0.x = (-u_xlat0.x) + 0.300000012;
    u_xlati27 = int((0.0<u_xlat0.x) ? 0xFFFFFFFFu : uint(0));
    u_xlati1 = int((u_xlat0.x<0.0) ? 0xFFFFFFFFu : uint(0));
    u_xlati18.y = (-u_xlati27) + u_xlati1;
    u_xlat18.xy = vec2(u_xlati18.xy);
    u_xlat27 = u_xlat18.y + 1.0;
    u_xlat27 = u_xlat27 + u_xlat27;
    u_xlatb0 = abs(u_xlat0.x)>=u_xlat9.x;
    u_xlat0.x = (u_xlatb0) ? 0.0 : u_xlat18.x;
    u_xlat1.xyw = u_xlat0.xxx * u_xlat2.xyz;
    u_xlat2.xyz = vec3(u_xlat27) * u_xlat1.xyw;
    u_xlat9.x = _reflection * -0.25 + 0.25;
    u_xlat2.xyz = (-u_xlat2.xyz) * u_xlat9.xxx + u_xlat1.xyw;
    u_xlat18.x = u_xlat27 * u_xlat0.x;
    u_xlat2.w = (-u_xlat18.x) * u_xlat9.x + u_xlat0.x;
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlat3 = u_xlat0 * u_xlat2;
    u_xlat4.xyz = u_xlat0.xyz + u_xlat2.xyz;
    u_xlat4.w = u_xlat0.w;
    u_xlat1 = (u_xlatb1.z) ? u_xlat3 : u_xlat4;
    u_xlat3.xyz = u_xlat2.xyz;
    u_xlat1 = (int(_blend_mode) != 0) ? u_xlat1 : u_xlat3;
    if(_use_inner_mask != 0) {
        u_xlatb2.xy = equal(ivec4(_show_inner_mask, _b_clip_mask, _show_inner_mask, _show_inner_mask), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat0 = u_xlat0 * u_xlat5;
        u_xlat0 = u_xlat3 * u_xlat4 + u_xlat0;
        u_xlat2.x = u_xlat4.x * u_xlat0.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat0.w;
        fragColor.xyz = u_xlat0.xyz;
    } else {
        fragColor = u_xlat1;
    }
    return;
}
